const ORG="00000000-0000-4000-8000-00000000000a",OTHER="00000000-0000-4000-8000-00000000000b",STORE="00000000-0000-4000-8000-0000000000c1",OWNER="00000000-0000-4000-8000-000000000001",APPROVER="00000000-0000-4000-8000-000000000002",APPROVER2="00000000-0000-4000-8000-000000000003",WORKER="00000000-0000-4000-8000-000000000004";
const EMBEDS={access_entitlements:["access_entitlements","entitlement_id"],governed_identities:["governed_identities","identity_id"],sod_rule_definitions:["sod_rule_definitions","rule_id"],access_review_campaigns:["access_review_campaigns","campaign_id"]};
function database(seed={}){
  const tables={organization_members:[],establishment_members:[],establishments:[{id:STORE,organization_id:ORG}],custom_staff_members:[],api_clients:[],ai_agents:[],profiles:[],security_sessions:[],...seed},t=n=>tables[n]||(tables[n]=[]),state={tables,failRpc:new Set(),ignoreRevoke:false,banned:new Set(),banFails:false,calls:[]};
  const embed=(table,row,columns)=>{const out={...row};for(const[name,[target,fk]]of Object.entries(EMBEDS))if(columns.includes(`${name}(`))out[name]=t(target).find(x=>x.id===row[fk])||null;if(columns.includes("sod_mitigations("))out.sod_mitigations=t("sod_mitigations").filter(x=>x.conflict_id===row.id);if(table==="access_requests"&&columns.includes("access_entitlements("))out.access_entitlements=t("access_entitlements").find(x=>x.id===row.entitlement_id);return out};
  class Query{constructor(n){this.n=n;this.f=[];this.op="select";this.cols="*";this.lim=null}select(c="*",o={}){if(this.op==="select"){this.cols=c;this.head=o.head;this.count=o.count}else this.returning=true;return this}eq(k,v){this.f.push(x=>x[k]===v);return this}neq(k,v){this.f.push(x=>x[k]!==v);return this}in(k,v){this.f.push(x=>v.includes(x[k]));return this}is(k,v){this.f.push(x=>(x[k]??null)===v);return this}not(k,_o,v){this.f.push(x=>(x[k]??null)!==v);return this}lte(k,v){this.f.push(x=>x[k]&&Date.parse(x[k])<=Date.parse(v));return this}order(){return this}limit(n){this.lim=n;return this}insert(v){this.op="insert";this.v=v;return this}update(v){this.op="update";this.v=v;return this}delete(){this.op="delete";return this}upsert(v,o={}){this.op="upsert";this.v=v;this.o=o;return this}maybeSingle(){this.one="maybe";return this}single(){this.one="single";return this}
    run(){const rows=t(this.n),defaults=()=>({id:randomUUID(),created_at:new Date().toISOString(),updated_at:new Date().toISOString()});let result=[],error=null;
      const violates=row=>{if(this.n==="access_grants"&&row.source_type&&["jit","break_glass"].includes(row.source_type)&&!row.valid_until)return"valid_until required";if(this.n==="access_grants"&&row.status==="revoked"&&!(row.revocation_reason&&row.revocation_confirmed_at))return"revocation must be confirmed";if(this.n==="access_review_items"){const subject=t("governed_identities").find(x=>x.id===row.identity_id)?.user_id;if(subject&&(subject===row.reviewer_id||subject===row.decided_by))return"REVIEWER_CANNOT_REVIEW_OWN_ACCESS"}if(this.n==="break_glass_events"&&row.reviewer_id&&row.reviewer_id===row.used_by)return"reviewer must differ";return null};
      if(this.op==="insert"){const items=Array.isArray(this.v)?this.v:[this.v];for(const v of items){const row={...defaults(),...v},bad=violates(row);if(bad){error={message:bad};break}if(this.n==="security_events"&&rows.some(x=>x.source_domain===row.source_domain&&x.source_ref===row.source_ref&&x.source_event_id===row.source_event_id)){error={message:"duplicate",code:"23505"};break}rows.push(row);result.push(row)}}
      else if(this.op==="update"){const hit=rows.filter(x=>this.f.every(f=>f(x)));for(const x of hit){const next={...x,...this.v},bad=violates(next);if(bad){error={message:bad};break}Object.assign(x,this.v);result.push(x)}}
      else if(this.op==="delete"){const keep=rows.filter(x=>!this.f.every(f=>f(x)));tables[this.n]=keep}
      else if(this.op==="upsert"){const keys=(this.o.onConflict||"id").split(",");for(const v of Array.isArray(this.v)?this.v:[this.v]){const hit=rows.find(x=>keys.every(k=>x[k]===v[k]));if(hit){if(!this.o.ignoreDuplicates)Object.assign(hit,v);result.push(hit)}else{const row={...defaults(),...v};rows.push(row);result.push(row)}}}
      else result=rows.filter(x=>this.f.every(f=>f(x)));
      if(this.op==="select"&&this.lim)result=result.slice(0,this.lim);
      if(this.head)return{data:null,count:result.length,error:null};
      const data=result.map(x=>embed(this.n,x,this.cols));if(this.one){if(this.one==="single"&&!data.length)return{data:null,error:error||{message:"no rows"}};return{data:data[0]||null,error}}return{data,error}}
    then(a,b){return Promise.resolve(this.run()).then(a,b)}}
  return{state,from:n=>new Query(n),auth:{admin:{updateUserById:async id=>{if(state.banFails)return{error:{message:"AUTH_DOWN"}};state.banned.add(id);return{error:null}},getUserById:async id=>({data:{user:{banned_until:state.banned.has(id)?"2999-01-01T00:00:00Z":null}}})}},async rpc(name,a){state.calls.push(name);if(state.failRpc.has(name))return{data:null,error:{message:`${name}_DOWN`}};const org=a.requested_organization_id,user=a.requested_user_id;
    if(name==="rbac_read_effective_access"){const stores=t("establishments").filter(x=>x.organization_id===org).map(x=>x.id);return{data:{organization_members:t("organization_members").filter(x=>x.organization_id===org&&(!user||x.user_id===user)),establishment_members:t("establishment_members").filter(x=>stores.includes(x.establishment_id)&&(!user||x.user_id===user)),store_access:[],module_permissions:t("module_permissions").filter(x=>x.organization_id===org&&(!user||x.user_id===user))},error:null}}
    if(name==="rbac_apply_establishment_role"){const row=t("establishment_members").find(x=>x.user_id===user&&x.establishment_id===a.requested_establishment_id);if(row?.role==="owner")return{data:null,error:{message:"RBAC_OWNER_PROTECTED"}};const previous=row?.role||null;if(row)row.role=a.requested_role;else t("establishment_members").push({user_id:user,establishment_id:a.requested_establishment_id,role:a.requested_role,status:"active"});return{data:{previous_role:previous},error:null}}
    if(name==="rbac_revoke_establishment_role"){const row=t("establishment_members").find(x=>x.user_id===user&&x.establishment_id===a.requested_establishment_id);if(row?.role==="owner")return{data:null,error:{message:"RBAC_OWNER_PROTECTED"}};if(!state.ignoreRevoke&&row?.role===a.requested_role)tables.establishment_members=t("establishment_members").filter(x=>x!==row);return{data:{},error:null}}
    if(name==="rbac_apply_organization_role"){const row=t("organization_members").find(x=>x.user_id===user&&x.organization_id===org);if(row?.role==="owner")return{data:null,error:{message:"RBAC_OWNER_PROTECTED"}};const previous=row?.role||null;if(row)row.role=a.requested_role;else t("organization_members").push({user_id:user,organization_id:org,role:a.requested_role,active:true});return{data:{previous_role:previous},error:null}}
    if(name==="rbac_revoke_organization_role"){const row=t("organization_members").find(x=>x.user_id===user&&x.organization_id===org);if(row?.role==="owner")return{data:null,error:{message:"RBAC_OWNER_PROTECTED"}};if(row?.role===a.requested_role)tables.organization_members=t("organization_members").filter(x=>x!==row);return{data:{},error:null}}
    if(name==="rbac_set_module_permission"){tables.module_permissions=t("module_permissions").filter(x=>!(x.user_id===user&&x.permission_key===a.requested_permission_key));if(a.requested_active)t("module_permissions").push({organization_id:org,user_id:user,module:a.requested_module,permission_key:a.requested_permission_key});return{data:{},error:null}}
    if(name==="rbac_offboard_employee_records"){let n=0;for(const s of t("custom_staff_members"))if(s.user_id===user){s.status="inactive";n++}return{data:{remaining_active:0,updated:n},error:null}}
    if(name==="rbac_revoke_user_sessions"){let revoked=0;for(const s of t("security_sessions"))if(s.user_id===user&&!s.revoked_at&&(s.organization_id===org||(a.requested_include_global&&!s.organization_id))){s.revoked_at=new Date().toISOString();revoked++}return{data:{revoked,remaining:t("security_sessions").filter(s=>s.user_id===user&&!s.revoked_at&&(s.organization_id===org||(a.requested_include_global&&!s.organization_id))).length},error:null}}
    if(name==="rbac_revoke_api_client"){const c=t("api_clients").find(x=>x.id===a.requested_client_id);if(c)c.status="revoked";return{data:{status:c?.status},error:null}}
    return{data:null,error:{message:`unexpected ${name}`}}}};
}
async function world(seed={},settings={}){
  const admin=database({organization_members:[{organization_id:ORG,user_id:OWNER,role:"owner",active:true},{organization_id:ORG,user_id:APPROVER,role:"admin",active:true},{organization_id:ORG,user_id:APPROVER2,role:"admin",active:true},{organization_id:ORG,user_id:WORKER,role:"member",active:true}],establishment_members:[{user_id:WORKER,establishment_id:STORE,role:"attendant",status:"active"},{user_id:OWNER,establishment_id:STORE,role:"owner",status:"active"}],identity_governance_settings:[{organization_id:ORG,require_mfa_for_privileged:false,expiry_warning_hours:24,break_glass_max_minutes:60,break_glass_review_hours:72,break_glass_requires_incident:false,jit_max_minutes:240,dormant_days:90,review_due_days:30,pre_approved_jit_keys:[],...settings}],...seed});
  await syncCatalog(admin,ORG);await syncIdentities(admin,ORG);
  const entitlement=key=>admin.state.tables.access_entitlements.find(x=>x.key===key),identity=user=>admin.state.tables.governed_identities.find(x=>x.user_id===user),request=key=>{const e=entitlement(key);e.requestable=true;e.status="active";return e},ctx=actorId=>({admin,organizationId:ORG,storeId:STORE,actorId,aal:"aal1"});
  return{admin,entitlement,identity,request,ctx};
}
const SOON=new Date(Date.now()+30*864e5).toISOString();
const ask=(w,key,scope={establishment_id:STORE},extra={})=>createAccessRequest(w.ctx(WORKER),{identityId:w.identity(WORKER).id,entitlementId:w.request(key).id,scope,justification:"Preciso cobrir a gerência esta semana.",durationHours:24,idempotencyKey:randomUUID(),...extra});
const events=(w,kind)=>w.admin.state.tables.security_events?.filter(x=>x.source_domain==="identity"&&(!kind||x.source_ref===kind))||[];
const audits=(w,action)=>w.admin.state.tables.identity_governance_audit_events?.filter(x=>x.action===action)||[];

test("T01 sync creates governed identities without copying people",async()=>{const w=await world(),row=w.identity(WORKER);assert.equal(row.identity_ref,WORKER);assert.equal(row.full_name,undefined);assert.equal(row.email,undefined);assert.equal(w.admin.state.tables.governed_identities.filter(x=>x.user_id===WORKER).length,1)});
test("T01d re-sync does not duplicate identities",async()=>{const w=await world(),before=w.admin.state.tables.governed_identities.length;await syncIdentities(w.admin,ORG);assert.equal(w.admin.state.tables.governed_identities.length,before)});
test("T02f re-sync keeps owners edited by the organization",async()=>{const w=await world();w.entitlement("store_role:manager").owner_ref="dono";await syncCatalog(w.admin,ORG);assert.equal(w.entitlement("store_role:manager").owner_ref,"dono")});
test("T03d baseline revokes nothing and marks for review",async()=>{const w=await world(),r=await importBaseline(w.admin,ORG,OWNER);assert.equal(r.revocations,0);assert.ok(r.imported>=4);assert.equal(w.admin.state.tables.establishment_members.length,2);assert.ok(w.admin.state.tables.access_grants.every(x=>x.source_type==="migration_baseline"&&x.review_required))});
test("T04 access request end to end",async()=>{const w=await world(),{request}=await ask(w,"store_role:manager");assert.equal(request.status,"pending_approval");assert.ok(request.approval_id);const{request:done}=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"Cobertura aprovada."});assert.equal(done.status,"completed");assert.equal(w.admin.state.tables.establishment_members.find(x=>x.user_id===WORKER).role,"manager");const g=w.admin.state.tables.access_grants.find(x=>x.id===done.grant_id);assert.equal(g.status,"active");assert.deepEqual(g.approved_by,[APPROVER]);assert.ok(g.valid_until);assert.equal(g.source_type,"request");assert.ok(g.reason);assert.equal(g.scope_key,`store:${STORE}`);assert.equal(audits(w,"access_granted").length,1)});
test("T04b the approval is the Phase 32 record",async()=>{const w=await world(),{request}=await ask(w,"store_role:manager"),a=w.admin.state.tables.internal_approvals.find(x=>x.id===request.approval_id);assert.equal(a.source_type,"identity_access_request");assert.equal(a.status,"pending");await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"ok"});assert.equal(a.status,"approved");assert.equal(w.admin.state.tables.internal_approval_steps.length,1)});
test("T04c rejection provisions nothing",async()=>{const w=await world(),{request}=await ask(w,"store_role:manager"),{request:done}=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"rejected",reason:"Não aprovado."});assert.equal(done.status,"rejected");assert.equal(w.admin.state.tables.establishment_members.find(x=>x.user_id===WORKER).role,"attendant")});
test("T04d same idempotency key does not create a second request",async()=>{const w=await world(),key=randomUUID(),a=await ask(w,"store_role:manager",undefined,{idempotencyKey:key}),b=await ask(w,"store_role:manager",undefined,{idempotencyKey:key});assert.equal(b.deduplicated,true);assert.equal(a.request.id,b.request.id)});
test("T04e request without justification is refused",async()=>{const w=await world();await assert.rejects(ask(w,"store_role:manager",undefined,{justification:"curta"}),/JUSTIFICATION_REQUIRED/)});
test("T04f privileged request needs a duration",async()=>{const w=await world();await assert.rejects(ask(w,"store_role:manager",undefined,{durationHours:null}),/DURATION_REQUIRED_FOR_PRIVILEGED/)});
test("T04g duration above the catalog maximum is refused",async()=>{const w=await world();await assert.rejects(ask(w,"store_role:manager",undefined,{durationHours:24*30}),/DURATION_EXCEEDS_MAXIMUM/)});
test("T04h read-only entitlement cannot be requested",async()=>{const w=await world();await assert.rejects(ask(w,"module:finance",{},{}),/NO_OFFICIAL_PATH/)});
test("T04i scope of another tenant is refused",async()=>{const w=await world();await assert.rejects(ask(w,"store_role:manager",{establishment_id:"00000000-0000-4000-8000-0000000000ff"}),/SCOPE_NOT_IN_TENANT/)});
test("T05 self approval of critical access is blocked",async()=>{const w=await world(),e=w.request("org_role:analyst");e.criticality="critical";const{request}=await createAccessRequest(w.ctx(APPROVER),{identityId:w.identity(WORKER).id,entitlementId:e.id,justification:"Pedido feito pelo próprio aprovador.",durationHours:4,idempotencyKey:randomUUID()});await assert.rejects(decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"eu mesmo"}),/SELF_APPROVAL_BLOCKED/)});
test("T05b beneficiary cannot approve own access",async()=>{const w=await world(),{request}=await createAccessRequest(w.ctx(APPROVER),{identityId:w.identity(WORKER).id,entitlementId:w.request("store_role:manager").id,scope:{establishment_id:STORE},justification:"Pedido em nome de outra pessoa.",durationHours:4,idempotencyKey:randomUUID()});await assert.rejects(decideAccessRequest(w.ctx(WORKER),{requestId:request.id,decision:"approved",reason:"meu"}),/SELF_APPROVAL_BLOCKED/)});
test("T05c critical needs two different approvers, then preview and confirmation",async()=>{const w=await world(),e=w.request("store_role:manager");e.criticality="critical";const{request}=await ask(w,"store_role:manager"),first=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"um"});assert.equal(first.pendingApprovals,1);await assert.rejects(decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"dois"}),/ALREADY_DECIDED/);const second=await decideAccessRequest(w.ctx(APPROVER2),{requestId:request.id,decision:"approved",reason:"dois"});assert.ok(second.confirmation.confirmation_token);assert.equal(w.admin.state.tables.establishment_members.find(x=>x.user_id===WORKER).role,"attendant");const ledger=w.admin.state.tables.copilot_action_requests[0];assert.equal(ledger.source,"identity_governance");assert.equal(ledger.action_type,"IDGOV_GRANT_CRITICAL");assert.notEqual(ledger.confirmation_token_hash,second.confirmation.confirmation_token)});
test("T05d steps from other routes do not count toward approval",async()=>{const w=await world(),{request}=await ask(w,"store_role:manager");w.admin.state.tables.internal_approval_steps=[{approval_id:request.approval_id,approver_user_id:WORKER,decision:"approved"}];const e=w.entitlement("store_role:manager");e.criticality="critical";w.admin.state.tables.internal_approvals[0].required_approvals=2;const r=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"um"});assert.equal(r.pendingApprovals,1)});
test("T06c action token works once, only for whoever saw the preview",async()=>{const w=await world(),c=w.ctx(APPROVER),a=await openGovernedAction(c,{actionType:"IDGOV_DISABLE_IDENTITY",criticality:"critical",targetType:"user",targetIds:[WORKER],payload:{},preview:{},idempotencyKey:"k"});await assert.rejects(claimGovernedAction(w.ctx(OWNER),{actionId:a.action_id,token:a.confirmation_token}),/FORBIDDEN/);await assert.rejects(claimGovernedAction(c,{actionId:a.action_id,token:randomUUID()}),/TOKEN_INVALID/);await claimGovernedAction(c,{actionId:a.action_id,token:a.confirmation_token});await assert.rejects(claimGovernedAction(c,{actionId:a.action_id,token:a.confirmation_token}),/ALREADY_HANDLED/)});
test("T06d provisioning failure leaves a visible failed state",async()=>{const w=await world();w.admin.state.failRpc.add("rbac_apply_establishment_role");const{request}=await ask(w,"store_role:manager"),{request:done}=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"ok"});assert.equal(done.status,"failed");assert.match(done.failure_reason,/DOWN/);assert.equal(w.admin.state.tables.access_grants.find(x=>x.id===done.grant_id).status,"failed");assert.equal(events(w,"revocation_failed").length,1)});
test("T08 temporary access expires automatically and restores the base role",async()=>{const w=await world(),{request}=await ask(w,"store_role:manager");const{request:done}=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"ok"}),g=w.admin.state.tables.access_grants.find(x=>x.id===done.grant_id);g.valid_until=new Date(Date.now()-1000).toISOString();const r=await sweepExpirations(w.ctx(null));assert.equal(r.expired,1);assert.equal(g.status,"expired");assert.ok(g.revocation_confirmed_at);assert.equal(w.admin.state.tables.establishment_members.find(x=>x.user_id===WORKER).role,"attendant")});
test("T08b sweep is idempotent and catches up after downtime",async()=>{const w=await world(),{request}=await ask(w,"store_role:manager"),{request:done}=await decideAccessRequest(w.ctx(APPROVER),{requestId:request.id,decision:"approved",reason:"ok"}),g=w.admin.state.tables.access_grants.find(x=>x.id===done.grant_id);g.valid_until=new Date(Date.now()-86400000).toISOString();assert.ok((await sweepExpirations(w.ctx(null))).lagSeconds>80000);assert.equal((await sweepExpirations(w.ctx(null))).expired,0)});
test("T08c warning before expiry",()=>{const now=new Date("2026-01-01T00:00:00Z"),p=new TemporaryAccessService().plan([{id:"a",status:"active",valid_until:"2026-01-01T10:00:00Z"},{id:"b",status:"active",valid_until:"2026-02-01T00:00:00Z"},{id:"c",status:"active",valid_until:"2025-12-31T00:00:00Z"}],now,24);assert.deepEqual(p.warn,["a"]);assert.deepEqual(p.expire,["c"])});
