test("R09 a failed revocation past its validity is retried by the sweep",async()=>{const w=await world(),s=await jit(w,"store_role:manager");await approveJit(w.ctx(APPROVER),{sessionId:s.id});const a=await activateJit(w.ctx(WORKER),{sessionId:s.id}),grant=w.admin.state.tables.access_grants.find(x=>x.id===a.grant_id);grant.status="failed";grant.valid_until="2020-01-01T00:00:00Z";grant.revocation_reason="Validade encerrada.";const out=await sweepExpirations(w.ctx(null));assert.equal(out.expired,1);assert.equal(grant.status,"expired");assert.equal(w.admin.state.tables.jit_sessions.find(x=>x.id===s.id).status,"expired")});
test("R09b revoking a JIT grant also closes the session",async()=>{const w=await world(),s=await jit(w,"store_role:manager");await approveJit(w.ctx(APPROVER),{sessionId:s.id});const a=await activateJit(w.ctx(WORKER),{sessionId:s.id});await revokeGrant(w.ctx(APPROVER),{grantId:a.grant_id,reason:"Encerrado."});assert.equal(w.admin.state.tables.jit_sessions.find(x=>x.id===s.id).status,"revoked");assert.ok(w.admin.state.tables.privileged_sessions.every(x=>x.ended_at))});
test("R10 an elevation does not stack on another one",async()=>{const w=await world(),s=await jit(w,"store_role:manager");await approveJit(w.ctx(APPROVER),{sessionId:s.id});await activateJit(w.ctx(WORKER),{sessionId:s.id});const other=await jit(w,"store_role:kitchen");await approveJit(w.ctx(APPROVER),{sessionId:other.id});await assert.rejects(activateJit(w.ctx(WORKER),{sessionId:other.id}),/ELEVATION_ALREADY_ACTIVE/)});
test("R10b a JIT on access already held is refused and keeps it permanent",async()=>{const w=await world();await importBaseline(w.admin,ORG,OWNER);const base=w.admin.state.tables.access_grants.find(x=>x.entitlement_id===w.entitlement("store_role:attendant").id),s=await jit(w,"store_role:attendant");await approveJit(w.ctx(APPROVER),{sessionId:s.id});await assert.rejects(activateJit(w.ctx(WORKER),{sessionId:s.id}),/ACCESS_ALREADY_HELD/);assert.ok(!base.valid_until)});
test("R15 a failed review revocation can be decided again",async()=>{const w=await world();await importBaseline(w.admin,ORG,OWNER);const{campaign}=await createReviewCampaign(w.ctx(OWNER),{name:"Revisão",reviewType:"manager_review"}),item=w.admin.state.tables.access_review_items.find(x=>x.campaign_id===campaign.id&&x.entitlement_id===w.entitlement("store_role:attendant").id);w.admin.state.ignoreRevoke=true;assert.equal((await decideReviewItem(w.ctx(OWNER),{itemId:item.id,decision:"revoke",reason:"Sem uso."})).execution_status,"failed");w.admin.state.ignoreRevoke=false;assert.equal((await decideReviewItem(w.ctx(OWNER),{itemId:item.id,decision:"revoke",reason:"Sem uso."})).execution_status,"revoked")});
test("R15b the review run uses a type its table accepts",async()=>{const w=await world();await createReviewCampaign(w.ctx(OWNER),{name:"Revisão",reviewType:"privileged_review"});assert.equal(w.admin.state.tables.access_review_runs.at(-1).review_type,"admins")});
